class Solution:
    def threeSumMulti(self, arr: list[int], target: int) -> int:
        mod = 1000000007
        freq = [0] * 101
        for x in arr:
            freq[x] += 1
        ans = 0
        for a in range(101):
            for b in range(a, 101):
                c = target - a - b
                if c < b or c > 100:
                    continue
                if a == b == c:
                    ans += freq[a] * (freq[a] - 1) * (freq[a] - 2) // 6
                elif a == b:
                    ans += freq[a] * (freq[a] - 1) // 2 * freq[c]
                elif b == c:
                    ans += freq[a] * freq[b] * (freq[b] - 1) // 2
                else:
                    ans += freq[a] * freq[b] * freq[c]
        return ans % mod

