class Solution:
    def threeSumMulti(self, arr: list[int], target: int) -> int:
        mod = 1000000007
        right = [0] * 101
        for x in arr:
            right[x] += 1
        left = [0] * 101
        ans = 0
        for b in arr:
            right[b] -= 1
            for a in range(101):
                c = target - a - b
                if 0 <= c <= 100:
                    ans += left[a] * right[c]
            left[b] += 1
        return ans % mod

